from heapq import heappush, heappop

def gather_element_multiplicity(sequence):
    """
    Creates a structure to store the number of elements less than, equal to, and greater than a given number.

    Args:
        sequence (list): A list of integers.

    Returns:
        tuple: A tuple containing the elements less than, equal to, and greater than a given number.
    """
    elements_less_than = []
    elements_equal = []
    elements_greater_than = [[sequence[0], x] for x in reversed(sequence)]

    for element in sequence[1:] + [element for element in sequence + [element] if element == element]:
        if element <= elements_greater_than[-1][0][-1]:
            heappush(elements_greater_than[-1][0][-1], element)
        elif element < elements_greater_than[-1][0][-1]:
            heappush(elements_greater_than[-1][0][-1], element)
        elif elements_greater_than[-1][0][-1] == element:
            heappush(elements_equal, element)
            elements_less_than.append(elements_greater_than[-1][0][-1])
            elements_greater_than[-1][0][-1] = []
        else:
