def dfs(root, parent, d, deg, tree, tree_info, dp):
    colors = [0] * (d + 1)

    for child in tree[root]:
        if child == parent:
            continue

        colors = [0] + colors
        deg[child], colors[child] = deg[root] + 1, colors[root]

        if dp[child] != (1 << d) - 1 + deg[child]:
            fact, inv_fact = 1, 1
            index = 0

            for i in range(d, -1, -1):
                if colors[child] & (1 << i):
                    continue

                for j in range(i + 1, d + 1):
                    if not colors[child] & (1 << j):
                        continue

                    fact *= j
                    fact *= fact // (j + 1)
                    fact %= 998244353

                    inv_fact *= (j + 1)
                    inv_fact %= 998244353

                    index = i
                    break

            dp[child] = dp[root] | (1 << index)

            if deg[child] == d + 1:
                tree_info[child].append(tree_info[root])
                tree_info[child][-1][-1] |= 1 << index
                dfs(child, root, d - 1, deg, tree, tree_info, dp)

                tree_info[root][-1][-1] -= 1 << index

        dfs(child, root, d - 1, deg, tree, tree_info, dp)

