            break
        choose_subjects = Counter()
        choose_scores = 0
        remainingSubjects = set(range(n))
        for i in range(n):
            if i in remainingSubjects and len(choose_subjects) < choose:
                choose_scores += S[i]
                choose_subjects[choose_subjects] += 1
                remainingSubjects.remove(i)
            elif S[i] > choose_scores and len(choose_subjects) < choose:
                choose_scores = S[i]
                choose_subjects[choose_subjects] += 1
                remainingSubjects.remove(i)
            else:
                break
        if total_credit := sum(choose_subjects[i] * (i + 1) for i in remainingSubjects):
            max_cpi = max(max_cpi, (choose_scores * choose + total_credit) / choose)

