def count_palindromic_substrings(s):
    def is_palindrome(start, end):
        while start < end:
            if s[start] != s[end]:
                return False
            start += 1
            end -= 1
        return True

    n = len(s)
    palindromes = []
    for i in range(n):
        for j in range(i + 1, n):
            if is_palindrome(i, j):
                palindromes.append(s[i:j+1])

    ways = 0
    for i in range(1, len(palindromes)):
        if len(palindromes[i]) < len(palindromes[i-1]):
            ways += 1

    return len(palindromes) * (len(palindromes) - 1) // 2 - ways // 2

