import math
from collections import defaultdict

def count_interesting_cases(maxn, maxa, q):
    mod_inv = [1]
    for i in range(1, q + 1):
        mod_inv.append(mod_inv[-1] * i % q)

    def powmod(base, power):
        result = 1
        while power:
            if power & 1:
                result = (result * base) % q
            base = (base * base) % q
            power >>= 1
        return result % q

    def gcd(a, b):
        while b:
            a, b = b, a % b
        return a

    def solve_locked(a, n):
        g = gcd(*a)
        b = a[0] // g
        return (len(b) * (len(b) - 1) // 2) * mod_inv[len(b) - 1] % q

    def solve_unlocked(a, n):
        g = gcd(*a)
        b = a[0] // g
        mod = powmod(g, -1, q)
        z = sum(v * mod_inv[i] for i, v in enumerate(n)) % q
        return z * powmod(len(b), 2, q) % q

    # Possible cases based on the formula of x for both wrong solutions
    locked_cases = [solve_locked([i, i + n], n) for i in range(1, maxa)]
    unlocked_cases = [solve_unlocked([i, i + n], n) for i in range(1, maxa)]
    interesting_cases = {}

    for case in locked_cases:
        if case not in interesting_cases:
            interesting_cases[case] = 1
        for unlocked_case in unlocked_cases:
            if (key := gcd(*case)) and (left := unlocked_case[0] // key) in interesting_cases:
                interesting_cases[key] |= interesting_cases[unlocked_case]

    # Counting the number of interesting cases that can occur
    return sum(count for case, count in interesting_cases.items() if proc[case] > 0) % q

