    if n < k or k < 0 or n < 0:
        return 0
    return mod_mul(fac[n], mod_mul(inv_fac[k], inv_fac[n - k]))

# Function to find the number of valid paths modulo MOD
def find_even_odd_paths(n, p, colors):
    valid_paths = 0

    # Count the number of paths where colors at the start of the path are even and those are odd
    for parity_shifts, parity in product(range(-2 * n + 1, 2 * n), repeat=n):
        for color_shift in range(pow(2, n)):
            current_path = 0
            alternate_colors = (color_shift << parity) | (parity_shifts * pow(2, n) + 1)
            for piece in range(n):
                if colors[piece] == -1:
                    current_path = (current_path << 1) | alternate_colors
                if colors[piece] == 0 and not (piece < current_path % pow(2, n) or piece > (current_path ^ 1) % pow(2, n)):
                    current_path += 1
            if current_path % pow(2, n) == current_path >> (p - size_t(1)):
                valid_paths += 1

    return valid_paths

