def is_at_boundary(r, c, grid, marked, direction, num=1):
    rows, cols = len(grid), len(grid[0])
    for xx in range(max(0, r+num), min(rows, r+num+1)):
        for yy in range(max(0, c+num), min(cols, c+num+1)):
            nr, nc = xx+r, yy+c
            dirn = 1 if direction == 0 else 0
            if 0 <= nr < rows and 0 <= nc < cols and not marked[nr][nc] and grid[nr][nc] in "EW":
                break
        else:
            continue
        if direction % 2 == 0 :
            num += lambda: grid[nr-1][nc] in "0?"
        else:
            num += lambda: grid[nr][nc-1] in "0?"
        if direction == 1:
            break
    return (num == num + len(direction))

# Function to check if a given room is a rectangle
def is_rectangle(room, dir, num=0):
    if "0?*" in room:
        return False
    for i, symbol in enumerate(room):
        # Calculate next cell depending on the direction
        next_symbol = "." if i + 1 < len(room) else room[0]
        # Check if next cell represents the same symbol
        if symbol == next_symbol:
            continue
        # Check if next cell represents a "U" character
        if symbol in "U" and next_symbol in ":\\" or symbol in "G" and next_symbol in "/\\":
            return False
    # Check if other cells are empty
    empty_value = "0" * num + " " * (len(room) + num - 1)
    if '*'.join(room).strip('*').replace('.*', '*0').replace('0.', '*1') != empty_value:
        return False
    return True

