import sys

def simulate_ripper_tree(N, M, shakes):
    tree = [[] for _ in range(N + 1)]
    for u, v in [(u - 1, v - 1) for u, v in sys.stdin.readline().split('\n')[:-1]]:
        tree[u].append(v)
        tree[v].append(u)

    leaves = [i for i in range(1, N + 1) if len(tree[i]) == 1]
    R = [0] * (N + 1)

    def get_single(tree, index, new_index):
        if len(tree[index]) == 1:
            tree[index].append(new_index)
            return tree[index][-1]
        else:
            return get_single(tree, tree[index].pop(), new_index)

    for shake in shakes:
        R[0] = 0
        for i in sorted(leaves):
            R[i] = get_single(tree, i, shake)
        R[0] += len(set(R[1:]))

    return R[0]

