            res = res * b % mod
        b = b * b % mod
        e >>= 1
    return res

def solve(n, k):
    dp = [[0] * (k + 1) for _ in range(n + 1)]
    dp[1][0] = 1

    for i in range(2, n + 1):
        curr = 1
        for x in range(i - 1):
            c = power(x, i - x - 1)
            for j in range(k - (x + 1) + 1):
                if j == 0:
                    dp[i][j] = curr * c % mod
                else:
                    dp[i][j] =  (dp[i - x - 1][j - 1] + dp[i - x - 1][j - 2] * c) % mod
            curr = curr * dp[i - 1][j] * power(j + 1, i - 2) % mod
    return dp[n][k]

