def compute_dist_starting_at_vertex(graph, start):
    dist_to_start = {v: float("inf") for v in range(len(graph))}
    stack = [(start, float("inf"))]
    while stack:
        vertex, dist = stack.pop()
        if dist < dist_to_start[vertex]:
            dist_to_start[vertex] = dist
            if vertex < len(graph) - 1:
                stack.append((graph[vertex], dist + dijkstra[graph[vertex]][vertex] + dijkstra[graph[vertex]][vertex] + 2))
            if vertex > 0:
                stack.append((graph[vertex], dist + dist_from_start[start][graph[vertex]]))
    return dist_to_start

def compute_dist_end_vertex(graph, start):
    dist_to_end = {v: float("inf") for v in range(len(graph))}
    stack = [(len(graph) - 1, float("inf"))]
    while stack:
        vertex, dist = stack.pop()
        if dist < dist_to_end[vertex]:
            dist_to_end[vertex] = dist
            if vertex > 0:
                stack.append((graph[vertex], dist + dist_from_end[start][vertex] + 2 * dist_from_end[start][graph[vertex]]))
            if vertex > 1:
                stack.append((graph[vertex], dist + dist_from_end[start][graph[vertex]]))
    return dist_to_end

def query(x, y, dist_start, dist_end):
    delta1 = 0
    before = float("inf")
    for i in range(1, len(dist_end) - 1):
        target = dist_end[x][i] - dist_end[y][i]
        if target > before:
            delta1 += i * (target - before)
        before = target
    delta2 = 0
    before = float("inf")
    for i in range(1, len(dist_start) - 1):
        target = dist_start[i][y] - dist_start[i][x]
        if target > before:
            delta2 += (len(dist_start) - i) * (target - before)
        before = target
    return delta1 - delta2

