from collections import deque

def bfs(start, grid, R, C):
    queue = deque([start])
    visited = set([start])
    dx = [-1, 1, 0, 0]
    dy = [0, 0, -1, 1]
    answer = 0

    while queue:
        x, y = queue.popleft()
        for i in range(4):
            nx = x + dx[i]
            ny = y + dy[i]

            if 0 <= nx < R and 0 <= ny < C and grid[nx][ny] == '.' and (nx, ny) not in visited:
                visited.add((nx, ny))
                queue.append((nx, ny))
                answer += 1

    return answer

def find_shortest_path(R, C, grid):
    start = (0, 0)
    visited = []

    for i in range(R):
        for j in range(C):
            if grid[i][j] == '.':
                visited.append((i,j))

    if not visited:
        return 0

    visited.sort()
    answer = float('inf')

    for x in range(len(visited) // 2):
        for y in range(len(visited)):
            if y > x:
                mx = visited[y][0]
                my = visited[y][1]

    grid[mx][my] = '*'
    answer = bfs((mx, my), grid, R, C)

    return answer

def make_rectangle(grid, R, C):
    queue = deque([(0, 0)])
    path = []
    visited = set()
    total = 0

    while queue:
        x, y = queue.popleft()
        path.append((x, y))
        visited.add((x, y))

        connected = find_shortest_path(R, C, grid)

        if connected < (x // 2) ** 2:
            for y in range(x + 1, R):
                flag = False
                for i in range(x):
                    for j in range(y - x + i):
                        if (i + 1, j + x - i - 1) not in visited:
                            flag = True
                            break

                if flag == False:
                    grid[x][y] = '*'
                    connected += 1
                elif flag == False:
                    for i in range(x):
                        for j in range(y - x + i):
                            if (i + 1, j + x - i - 1) not in visited:
                                path.append((i + 1, j + x - i - 1))
                                visited.add((i + 1, j + x - i - 1))
                                path.remove((i + 1, j + x - i - 1))

                total += 1

        if path == sorted(path):
            break

    return grid, total

