def qsort(nums, reverse=True, inside=True):
    if inside:
        nums.sort(reverse=reverse)
    else:
        pairs = []
        for i in range(len(nums)):
            pairs.append((-nums[i], i+1))
        nums.sort(key=lambda item: item[0], reverse=reverse)
        return [item[1] for item in pairs], nums

