                    increment += interesting_case_counts[(n, a1, a2)]
            for a in range(a1 + 1, maxa + 1):
                increment += interesting_case_counts[(n, a1, a2) - (n, a1, a)]
            interesting_case_counts[(n, a1, a)] += increment % q

