    cache = [(0, 0)]

    for color in colors:
        for i in range(len(cache)):
            base = cache[i]
            if parity == 0:
                (summ1, summ2) = (0, base[1])
            else:
                (summ1, summ2) = (base[1], 0)
            for j in range(len(cache)):
                temp = cache[j]
                (summ1, summ2) = (modular_exponentiation(summ1 + parity <= temp[0], mod) % mod, modular_exponentiation(summ2 + parity >= temp[1], mod) % mod)

            if parity:
                (summ1, summ2) = (summ1 + base[1] * temp[1] % mod, mod - summ2)
            else:
                (summ1, summ2) = (summ1 + base[1] * temp[1] % mod, (summ2 + base[1] * temp[1] % mod + mod - 1) % mod)

            cache.append((summ1, summ2))
        if parity == 0:
            parity = 1
        else:
            parity = 0

    return cache[-1]

