from collections import defaultdict
from math import gcd

def collect_divisor_per_hash(divisor):
    divisors = [1]
    while True:
        for d in range(2, divisor):
            if divisor % d == 0 and divisor / d % 2 == 1: 
                divisors.append(d)
        if (divisor % 2 == 1):
            break
        divisor //= 2
    return divisors

MOD = 10**9 + 7

# Function to calculate exponentiation with bound on base
def mod_pow(x, n):
    return pow(x, n, MOD)

# Function to calculate gcd using Euclid's algorithm
def gcd_extended(a, b):
    if a == 0: 
        return (b, 0, 1)
    gcd, x1, y1 = gcd_extended(b % a, a)
    x = y1 - (b // a) * x1
    y = x1
    return gcd, x, y

# Main function to calculate binomial coefficient modulo 10^9 + 7
def binom_mod_n(n, k, MOD=10**9 + 7):
    if k < 0 or k > n:
        return 0
    elif k == 0 or k == n:
        return 1
    binom = (n * mod_pow(n - k, MOD - 2) * mod_pow(k, MOD - 2)) % MOD
    fnk = gcd_extended(n, k)
    divisors = collect_divisor_per_hash(fnk[0])
    trash = divisors.pop()
    for d in divisors:
        if d == 2:
            binom = (binom * d) % MOD
        else:
            binom = (binom * ((d - 1) // 2) ** k * (d + 1) // 2 * binom_mod_n(d - 2, k, MOD) % MOD)
    return binom % MOD

def calculate_paths(start, end, is_target, pieces):
    if not is_target and start > end:
        return binom_mod_n(pieces[end + 1] + 1, pieces[end]) % MOD
    elif not is_target and pieces[start - 1] < pieces[end] > pieces[start]:
        return (binom_mod_n(pieces[end] - 1, pieces[start], MOD) + MOD) % MOD
    elif is_target and start > end:
        return binom_mod_n(pieces[start] + 1, pieces[end + 1], MOD)
    elif is_target and pieces[start - 1] < pieces[end] > pieces[start]:
        return (binom_mod_n(pieces[end] - 1, pieces[start], MOD) + MOD) % MOD
    elif is_target:
        return 0

