import math

def calculate_illuminated_area(n, h, f, points):
    min_y = -h
    max_y = h
    for point in points:
        for y in [min_y, max_y]:
            if y < point < y + h:
                yield y, y + h

    for point in points:
        if point[0] < 0:
            yield max(point[0], -f), min(point[1], f)
        elif point[1] < 0:
            yield max(point[0], f), min(point[1], h)
        else:
            yield min(point[0], h), max(point[1], -h)

    if points:
        output = sum(start + end for start, end in calculate_illuminated_area(n - 1, h, f, points) if start + end != (1, 1))
    else:
        output = max_y - min_y

    return output * 1.0

def main():
    import sys
    input = sys.stdin.read
    data = input().split()

    n, h, f = map(int, data[0:3])
    points = [tuple(map(int, data[i * 2 : i * 2 + 2])) for i in range(1, n + 1)]

    print("{:.10f}".format(calculate_illuminated_area(n, h, f, points)))

if __name__ == "__main__":
    main()
