def is_palindrome(s):
    return s == s[::-1]

def count_palindromic_subsequences(s):
    n = len(s)
    dp = [[0] * n for _ in range(n)]

    for i in range(n):
        dp[i][i] = 1  # Each character is a palindrome of length 1

    for l in range(2, n + 1):
        for i in range(n - l + 1):
            j = i + l - 1
            if is_palindrome(s[i:j+1]):
                dp[i][j] = 1
            else:
                for k in range(i, j):
                    dp[i][j] += dp[i][k] + dp[k+1][j] - dp[i][k] - dp[k+1][j]
                dp[i][j] += dp[i][j]  # Adding the palindrome count of empty subsequences

    return dp[0][-1]

# Example
S = "abba"
print(count_palindromic_subsequences(S))
